create or replace function app.finance_invoice_margin_summary(p_invoice_id uuid) returns jsonb language plpgsql stable security definer set search_path='' as $$declare v public.finance_invoices%rowtype;v_est numeric:=0;v_direct numeric:=0;v_agent numeric:=0;v_partner numeric:=0;v_marketing numeric:=0;v_payment_fee numeric:=0;v_opex numeric:=0;v_tax_exp numeric:=0;v_other numeric:=0;v_net_revenue numeric:=0;v_total_cost numeric:=0;begin if not(app.has_permission('finance_invoices.create') or app.has_permission('finance_expenses.record') or app.has_permission('financial_reports.view')) then raise exception 'Missing finance permission.' using errcode='42501';end if;select * into v from public.finance_invoices where id=p_invoice_id;if not found then raise exception 'Invoice not found.' using errcode='P0002';end if;select coalesce(sum(coalesce(estimated_cost_total,coalesce(estimated_unit_cost,0)*quantity)),0) into v_est from public.finance_invoice_items where invoice_id=p_invoice_id;select coalesce(sum(total_amount) filter(where cost_class='direct_cost'),0),coalesce(sum(total_amount) filter(where cost_class='agent_fee'),0),coalesce(sum(total_amount) filter(where cost_class='partner_fee'),0),coalesce(sum(total_amount) filter(where cost_class='marketing_fee'),0),coalesce(sum(total_amount) filter(where cost_class='payment_fee'),0),coalesce(sum(total_amount) filter(where cost_class='operating_expense'),0),coalesce(sum(total_amount) filter(where cost_class='tax'),0),coalesce(sum(total_amount) filter(where cost_class='other'),0) into v_direct,v_agent,v_partner,v_marketing,v_payment_fee,v_opex,v_tax_exp,v_other from public.finance_expenses where invoice_id=p_invoice_id and status='recorded';v_net_revenue:=greatest(0,v.paid_total-v.refunded_total);v_total_cost:=v_direct+v_agent+v_partner+v_marketing+v_payment_fee+v_opex+v_tax_exp+v_other;return jsonb_build_object('invoice_id',v.id,'currency',v.currency,'sales_value',v.grand_total,'invoice_tax',v.tax_total,'estimated_hpp',v_est,'estimated_margin',v.grand_total-v_est,'estimated_margin_percent',case when v.grand_total>0 then round(((v.grand_total-v_est)/v.grand_total)*100,2) else 0 end,'net_cash_revenue',v_net_revenue,'actual_direct_cost',v_direct,'agent_fee',v_agent,'partner_fee',v_partner,'marketing_fee',v_marketing,'payment_fee',v_payment_fee,'allocated_opex',v_opex,'tax_expense',v_tax_exp,'other_cost',v_other,'total_linked_cost',v_total_cost,'actual_margin_before_indirect_costs',v_net_revenue-v_direct-v_agent-v_partner-v_marketing-v_payment_fee,'actual_margin_after_linked_costs',v_net_revenue-v_total_cost,'actual_margin_percent',case when v_net_revenue>0 then round(((v_net_revenue-v_total_cost)/v_net_revenue)*100,2) else 0 end,'hpp_variance',v_direct-v_est);end$$;